add_expense:
function add_expense(amount, category, note) {
  const n = Number(amount);
  if (!Number.isFinite(n) || typeof amount === "boolean") {
    throw new Error("amount must be a number");
  }
  if (n <= 0) {
    throw new Error("amount must be greater than zero");
  }
  if (typeof category !== "string" || category.trim() === "") {
    throw new Error("category is required");
  }
  state.expenses = state.expenses || [];
  const expense = { amount, category };
  if (typeof note === "string") expense.note = note;
  state.expenses.push(expense);
  return state.expenses.length;
}

total:
function total() {
  const expenses = state.expenses || [];
  const toCents = (amount) => {
    const n = Number(amount);
    if (!Number.isFinite(n)) return 0;
    const scaled = Number(n + "e2");
    return Math.round(Number.isFinite(scaled) ? scaled : n * 100);
  };
  let cents = 0;
  for (const expense of expenses) {
    cents += toCents(expense && expense.amount);
  }
  return cents / 100;
}

by_category:
function by_category() {
  const expenses = state.expenses || [];
  const toCents = (amount) => {
    const n = Number(amount);
    if (!Number.isFinite(n)) return 0;
    const scaled = Number(n + "e2");
    return Math.round(Number.isFinite(scaled) ? scaled : n * 100);
  };
  const cents = {};
  const keys = [];
  for (const expense of expenses) {
    const amount = Number(expense && expense.amount);
    if (!Number.isFinite(amount)) continue;
    const key = String(expense.category);
    if (!Object.prototype.hasOwnProperty.call(cents, key)) {
      cents[key] = 0;
      keys.push(key);
    }
    cents[key] += toCents(amount);
  }
  const map = {};
  for (const key of keys) map[key] = cents[key] / 100;
  return map;
}

set_budget:
function set_budget(category, amount) {
  const n = Number(amount);
  if (!Number.isFinite(n) || typeof amount === "boolean") {
    throw new Error("amount must be a number");
  }
  if (n < 0) {
    throw new Error("amount must not be negative");
  }
  state.budgets = state.budgets || {};
  state.budgets[category] = amount;
  return state.budgets[category];
}

over_budget:
function over_budget() {
  const budgets = state.budgets || {};
  const spent = by_category();
  const toCents = (amount) => {
    const n = Number(amount);
    if (!Number.isFinite(n)) return 0;
    const scaled = Number(n + "e2");
    return Math.round(Number.isFinite(scaled) ? scaled : n * 100);
  };
  const over = [];
  for (const category of Object.keys(budgets)) {
    const budgetCents = toCents(budgets[category]);
    const spentCents = toCents(spent[category] === undefined ? 0 : spent[category]);
    if (spentCents > budgetCents) {
      over.push({ category, over: spentCents - budgetCents });
    }
  }
  over.sort((a, b) => b.over - a.over || (a.category < b.category ? -1 : a.category > b.category ? 1 : 0));
  return over.map((entry) => entry.category);
}

top_category:
function top_category() {
  const totals = by_category();
  const toCents = (amount) => {
    const n = Number(amount);
    if (!Number.isFinite(n)) return 0;
    const scaled = Number(n + "e2");
    return Math.round(Number.isFinite(scaled) ? scaled : n * 100);
  };
  let best = null;
  let bestCents = 0;
  const categories = Object.keys(totals).sort();
  for (const category of categories) {
    const cents = toCents(totals[category]);
    if (best === null || cents > bestCents) {
      best = category;
      bestCents = cents;
    }
  }
  return best;
}
